package nextup.view;

import java.util.Scanner;

/**
 * OWNER: Al-Farouq Mohamed. Owns the program's only Scanner. Reads a line
 * of text, or a valid menu number (re-prompting on a bad choice). Both
 * views share one ConsoleInput.
 *
 * Taking the Scanner in the constructor is what makes this testable: a test
 * passes new Scanner("abc\n9\n2\n") instead of the keyboard.
 *
 * @author Al-Farouq Mohamed (alfarouqm18)
 * @version 2026.11.08
 */
public class ConsoleInput {

    private final Scanner scanner;

    /**
     * Creates the reader.
     *
     * @param scanner
     *            where input comes from (new Scanner(System.in) in Runner)
     */
    public ConsoleInput(Scanner scanner) {
        this.scanner = scanner;
    }


    /**
     * Prints the prompt and reads one whole line.
     *
     * @param prompt
     *            what to print first, e.g. "Your name: "
     * @return the line typed (may be blank), or null if input has ended
     *         (Ctrl+D) so the caller can stop cleanly
     */
    public String readLine(String prompt) {
        // Print first: hasNextLine() waits for the user to type, so
        // checking it before printing would show each prompt too late.
        System.out.print(prompt);
        System.out.flush();
        if (!scanner.hasNextLine()) {
            return null;
        }
        return scanner.nextLine();
    }


    /**
     * Prints the prompt and reads a menu choice from 1 to max. Anything
     * else (9, abc, blank) prints "Enter a number 1 to MAX." and asks
     * again.
     *
     * @param prompt
     *            what to print first, e.g. "Choose: "
     * @param max
     *            the largest valid choice
     * @return a number from 1 to max, or -1 if input has ended
     */
    public int readMenuChoice(String prompt, int max) {
        while(true){
            String input = readLine(prompt);
            if(input == null){
                return -1;
            }
            try{
                int choice = Integer.parseInt(input.trim());
                if(choice >= 1 && choice <= max){
                    return choice;
                }
            }catch(NumberFormatException e){

            }

            System.out.println("Enter a number 1 to " + max + ".");
        }
    }
}
